ПР06_05_курсоры.sql.sql:
-- Q01. Явный курсор: построчный вывод бонусных карт в журнал сообщений.
DO $block$
DECLARE card_cursor CURSOR FOR
    SELECT lc.id_loyalty_card,c.name,lc.points FROM public.loyalty_card lc
    JOIN public.client c USING(id_client) ORDER BY lc.id_loyalty_card;
    row_data record;
BEGIN
    OPEN card_cursor;
    LOOP
        FETCH card_cursor INTO row_data;
        EXIT WHEN NOT FOUND;
        RAISE NOTICE 'Карта %, клиент %, баллы %',row_data.id_loyalty_card,row_data.name,row_data.points;
    END LOOP;
    CLOSE card_cursor;
END;
$block$;
-- Q02. Неявный курсор FOR ... IN: результат возвращается как таблица.
CREATE OR REPLACE FUNCTION rbd.employee_activity()
RETURNS TABLE(employee_id integer,employee_name text,session_count bigint)
LANGUAGE plpgsql AS $fn$
DECLARE row_data record;
BEGIN
    FOR row_data IN
        SELECT e.id_employee,e.name,count(rs.id_rental_session) AS sessions
        FROM public.employee e LEFT JOIN public.rental_session rs USING(id_employee)
        GROUP BY e.id_employee,e.name ORDER BY e.id_employee
    LOOP
        employee_id:=row_data.id_employee;
        employee_name:=row_data.name;
        session_count:=row_data.sessions;
        RETURN NEXT;
    END LOOP;
END;
$fn$;
SELECT * FROM rbd.employee_activity();

ПР07_01_генерация_20000_оплат.sql.sql:
-- Меняет таблицу public.payment: выполнить самостоятельно на учебной копии базы.
-- Маркер не позволяет этому скрипту повторно добавить те же 20 000 строк.
CREATE SCHEMA IF NOT EXISTS rbd;
CREATE TABLE IF NOT EXISTS rbd.generation_runs(
    run_name text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT current_timestamp,
    inserted_rows integer NOT NULL
);
BEGIN;
DO $block$
DECLARE methods integer[]; i integer;
BEGIN
    IF EXISTS(SELECT 1 FROM rbd.generation_runs WHERE run_name='practice7_payments') THEN
        RAISE NOTICE 'Генерация практики 7 уже выполнена; новые строки не добавлены';
        RETURN;
    END IF;
    SELECT array_agg(id_payment_method ORDER BY id_payment_method) INTO methods FROM public.payment_method;
    IF methods IS NULL THEN RAISE EXCEPTION 'Сначала заполните payment_method'; END IF;
    FOR i IN 1..20000 LOOP
        INSERT INTO public.payment(id_payment_method,amount,status,id_discount)
        VALUES(methods[1+(i-1)%array_length(methods,1)],100+(i*37)%5000,
            CASE WHEN i%100=0 THEN 'Оплата произведена'
                 WHEN i%20=0 THEN 'Ошибка оплаты' ELSE 'Ожидает оплаты' END,NULL);
    END LOOP;
    INSERT INTO rbd.generation_runs(run_name,inserted_rows) VALUES('practice7_payments',20000);
END;
$block$;
COMMIT;
ANALYZE public.payment;
SELECT count(*) AS all_payments FROM public.payment;
SELECT * FROM rbd.generation_runs WHERE run_name='practice7_payments';

ПР07_02_индексы_три_сценария.sql.sql:
-- Выполнять ПО БЛОКАМ: получить и сохранить ДО, затем создать индекс и получить ПОСЛЕ.
-- Условия каждого запроса до и после полностью совпадают.
-- Q01. Перед сравнением проверить существующие индексы.
SELECT indexname,indexdef FROM pg_indexes WHERE schemaname='public' AND tablename='payment';
ANALYZE public.payment;
-- Сценарий 1. B-Tree по сумме.
-- Q02. ДО.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment WHERE amount>=5000;
-- Q03. Создание индекса.
CREATE INDEX rbd_idx_payment_amount ON public.payment(amount);
ANALYZE public.payment;
-- Q04. ПОСЛЕ: тот же запрос.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment WHERE amount>=5000;
-- Сценарий 2. Индекс по выражению LOWER(status).
-- Q05. ДО.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment WHERE lower(status)='ошибка оплаты';
-- Q06. Создание индекса по выражению.
CREATE INDEX rbd_idx_payment_lower_status ON public.payment(lower(status));
ANALYZE public.payment;
-- Q07. ПОСЛЕ: тот же запрос.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment WHERE lower(status)='ошибка оплаты';
-- Сценарий 3. Частичный индекс только для успешно проведенных оплат.
-- Q08. ДО. Уже созданный B-Tree может использоваться: зафиксировать фактический план.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment
WHERE status='Оплата произведена' AND amount>=4000;
-- Q09. Создание частичного индекса.
CREATE INDEX rbd_idx_payment_paid_partial ON public.payment(amount)
WHERE status='Оплата произведена';
ANALYZE public.payment;
-- Q10. ПОСЛЕ: тот же запрос.
EXPLAIN(ANALYZE,BUFFERS) SELECT * FROM public.payment
WHERE status='Оплата произведена' AND amount>=4000;
-- Не подменять условия ДО/ПОСЛЕ и не отключать enable_seqscan ради результата.

ПР07_03_COMMIT.sql.sql:
-- Требуется rbd.bonus_redemption из практики 5 и карта 1 с >=50 баллами.
-- Бизнес-операция: уменьшить баллы и создать связанную запись списания.
SELECT * FROM public.loyalty_card WHERE id_loyalty_card=1;
BEGIN;
SELECT * FROM public.loyalty_card WHERE id_loyalty_card=1 FOR UPDATE;
DO $check$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.loyalty_card WHERE id_loyalty_card=1 AND points>=50) THEN
        RAISE EXCEPTION 'Карта 1 отсутствует либо баллов недостаточно';
    END IF;
END;
$check$;
UPDATE public.loyalty_card SET points=points-50 WHERE id_loyalty_card=1;
INSERT INTO rbd.bonus_redemption(id_loyalty_card,spent_points) VALUES(1,50);
COMMIT;
SELECT * FROM public.loyalty_card WHERE id_loyalty_card=1;
SELECT * FROM rbd.bonus_redemption WHERE id_loyalty_card=1 ORDER BY id_redemption;

ПР07_04_ROLLBACK.sql.sql:
-- Выполнять ПО ОПЕРАТОРАМ: отрицательное списание специально вызывает CHECK-ошибку.
SELECT * FROM public.loyalty_card WHERE id_loyalty_card=1;
SELECT count(*) FROM rbd.bonus_redemption WHERE id_loyalty_card=1;
BEGIN;
UPDATE public.loyalty_card SET points=points-10 WHERE id_loyalty_card=1;
INSERT INTO rbd.bonus_redemption(id_loyalty_card,spent_points) VALUES(1,-10);
-- После ожидаемой ошибки обязательно выполнить отдельно.
ROLLBACK;
SELECT * FROM public.loyalty_card WHERE id_loyalty_card=1;
SELECT count(*) FROM rbd.bonus_redemption WHERE id_loyalty_card=1;

ПР07_05_READ_COMMITTED_сеанс_A.sql.sql:
-- Отдельное подключение A. Не запускать файл целиком.
-- Шаг A1: проверить PID и начать транзакцию.
SELECT pg_backend_pid();
BEGIN ISOLATION LEVEL READ COMMITTED;
-- Шаг A2: запомнить первый результат, затем выполнить шаг B в другом подключении.
SELECT points FROM public.loyalty_card WHERE id_loyalty_card=1;
-- Шаг A3: выполнить только ПОСЛЕ COMMIT подключения B.
SELECT points FROM public.loyalty_card WHERE id_loyalty_card=1;
COMMIT;

ПР07_06_изменение_сеанс_B.sql.sql:
-- Отдельное подключение B. PID должен отличаться от PID подключения A.
SELECT pg_backend_pid();
-- Выполнить после первого SELECT в подключении A.
BEGIN;
UPDATE public.loyalty_card SET points=points+100 WHERE id_loyalty_card=1 RETURNING points;
COMMIT;
-- Теперь вернуться в A и выполнить второй SELECT.

ПР07_07_REPEATABLE_READ_сеанс_A.sql.sql:
-- Подключение A; предыдущая транзакция должна быть завершена.
-- Шаг A1.
SELECT pg_backend_pid();
BEGIN ISOLATION LEVEL REPEATABLE READ;
-- Шаг A2: после первого SELECT выполнить скрипт сеанса B и его COMMIT.
SELECT points FROM public.loyalty_card WHERE id_loyalty_card=1;
-- Шаг A3: внутри этой транзакции виден прежний снимок.
SELECT points FROM public.loyalty_card WHERE id_loyalty_card=1;
COMMIT;
-- После завершения транзакции становится видно новое значение.
SELECT points FROM public.loyalty_card WHERE id_loyalty_card=1;

ПР08_01_BYTEA_и_секции.sql.sql:
CREATE SCHEMA IF NOT EXISTS rbd;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;
-- Задание 1. Только учебные пароли из примера, не реальные пароли пользователя.
CREATE TABLE rbd.system_roles(id_role integer PRIMARY KEY,name varchar(100) NOT NULL UNIQUE);
CREATE TABLE rbd.system_users(
    id_user integer PRIMARY KEY,login varchar(100) NOT NULL UNIQUE,
    id_role integer NOT NULL REFERENCES rbd.system_roles(id_role),
    raw_password text NOT NULL,password_hash bytea NOT NULL
);
INSERT INTO rbd.system_roles VALUES(1,'Администратор'),(2,'Оператор'),(3,'Менеджер');
INSERT INTO rbd.system_users VALUES
(1,'poliektov',1,'DemoOnly_123',public.digest('DemoOnly_123','sha256')),
(2,'operator',2,'DemoOperator_456',public.digest('DemoOperator_456','sha256')),
(3,'manager',3,'DemoManager_789',public.digest('DemoManager_789','sha256'));
-- Q01. Успешная и неуспешная проверки в одном результате.
SELECT u.login,v.entered_password,
(u.password_hash=public.digest(v.entered_password,'sha256')) AS password_matches
FROM rbd.system_users u CROSS JOIN
(VALUES('DemoOnly_123'),('WrongDemoPassword')) AS v(entered_password)
WHERE u.login='poliektov';
-- Задание 2. RANGE по дате. PK включает ключ секционирования.
CREATE TABLE rbd.event_log(
    id_event bigint GENERATED ALWAYS AS IDENTITY,
    event_date date NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,
    PRIMARY KEY(event_date,id_event)
) PARTITION BY RANGE(event_date);
CREATE TABLE rbd.event_log_2024_h2 PARTITION OF rbd.event_log
FOR VALUES FROM('2024-07-01') TO('2025-01-01');
CREATE TABLE rbd.event_log_2025_h1 PARTITION OF rbd.event_log
FOR VALUES FROM('2025-01-01') TO('2025-07-01');
CREATE TABLE rbd.event_log_default PARTITION OF rbd.event_log DEFAULT;
-- Верхняя граница диапазона исключается; DEFAULT принимает любые остальные даты.
SELECT relid::regclass AS partition,isleaf FROM pg_partition_tree('rbd.event_log');

ПР08_02_генерация_20000_событий.sql.sql:
-- Задание 3. Генерация именно на PL/pgSQL, по одному событию в итерации.
BEGIN;
DO $block$
DECLARE i integer; day date; event_name text; event_payload jsonb;
BEGIN
    IF EXISTS(SELECT 1 FROM rbd.event_log) THEN
        RAISE EXCEPTION 'event_log уже заполнена: повторная генерация отменена';
    END IF;
    FOR i IN 1..20000 LOOP
        day:=DATE '2024-07-01'+((i-1)%730);
        IF i%2=0 THEN
            event_name:='rental_completed';
            event_payload:=jsonb_build_object('rental',jsonb_build_object(
                'amount',100+(i*13)%1400,'duration_hours',1+i%6),
                'client_number',1+i%5,'gaming_spot_number',1+i%20);
        ELSE
            event_name:='user_login';
            event_payload:=jsonb_build_object('login','client_'||(1+i%5),
                'success',i%7<>0,'device','club_pc_'||(1+i%20));
        END IF;
        INSERT INTO rbd.event_log(event_date,event_type,payload) VALUES(day,event_name,event_payload);
    END LOOP;
END;
$block$;
COMMIT;
-- Q01. Всего должно быть ровно 20 000 событий.
SELECT count(*) AS total_events FROM rbd.event_log;
-- Q02. Физическое распределение по секциям; все три должны содержать строки.
SELECT tableoid::regclass AS physical_partition,count(*) AS events,min(event_date),max(event_date)
FROM rbd.event_log GROUP BY tableoid ORDER BY tableoid::regclass::text;
-- Q03. Два типа событий имеют разные структуры JSON.
SELECT * FROM rbd.event_log WHERE event_type='rental_completed' ORDER BY id_event LIMIT 5;
SELECT * FROM rbd.event_log WHERE event_type='user_login' ORDER BY id_event LIMIT 5;

ПР08_04_изменение_JSONB.sql.sql:
-- Демонстрация выполняется в транзакции и затем откатывается.
BEGIN;
-- Q01. Массовое добавление ключа только событиям завершения сеанса.
UPDATE rbd.event_log SET payload=payload||'{"currency":"RUB"}'::jsonb
WHERE event_type='rental_completed';
-- Q02. Проверка: количество строк с ключом равно количеству завершений.
SELECT count(*) FILTER(WHERE event_type='rental_completed') AS rentals,
count(*) FILTER(WHERE payload ? 'currency') AS with_currency FROM rbd.event_log;
-- Q03. Значение в одной выбранной записи до изменения.
SELECT * FROM rbd.event_log WHERE (event_date,id_event)=
(SELECT event_date,id_event FROM rbd.event_log WHERE event_type='rental_completed' ORDER BY id_event LIMIT 1);
-- Q04. Изменение вложенного поля ровно у этой записи.
UPDATE rbd.event_log SET payload=jsonb_set(payload,'{rental,duration_hours}','6'::jsonb,false)
WHERE (event_date,id_event)=
(SELECT event_date,id_event FROM rbd.event_log WHERE event_type='rental_completed' ORDER BY id_event LIMIT 1)
RETURNING id_event,event_date,payload;
ROLLBACK;
